      if (c === '"' || c === "'") { inStr = c; i++; continue; }
      if (c === "`") { inTemplate = true; i++; continue; }
      if ("{[(".includes(c)) depth++;
      else if ("}])".includes(c)) depth = Math.max(0, depth - 1);
      i++;
